alter table public.profiles enable row level security;
drop policy if exists profiles_select_own on public.profiles; create policy profiles_select_own on public.profiles for select to authenticated using(auth.uid()=id);
drop policy if exists profiles_update_own on public.profiles; create policy profiles_update_own on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
do $$ declare t text; begin foreach t in array array['onboarding_states','career_experiences','interview_attempts','self_introduction_attempts','application_answers','application_answer_versions','learning_events','weekly_plans','user_settings','sync_metadata','user_audio_files'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists %I_select_own on public.%I',t,t); execute format('create policy %I_select_own on public.%I for select to authenticated using(auth.uid()=user_id)',t,t); execute format('drop policy if exists %I_insert_own on public.%I',t,t); execute format('create policy %I_insert_own on public.%I for insert to authenticated with check(auth.uid()=user_id)',t,t); execute format('drop policy if exists %I_update_own on public.%I',t,t); execute format('create policy %I_update_own on public.%I for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id)',t,t); execute format('drop policy if exists %I_delete_own on public.%I',t,t); execute format('create policy %I_delete_own on public.%I for delete to authenticated using(auth.uid()=user_id)',t,t); end loop; end $$;
